  "auth.consent.merchant": "ਮੈਨੂੰ {shop} ਦੇ ਆਫ਼ਰ ਟੈਕਸਟ ਰਾਹੀਂ ਭੇਜੋ (ਵਿਕਲਪਿਕ)। ਇਹ ਡੱਬਾ ਤੁਹਾਡੇ ਲਈ ਪਹਿਲਾਂ ਤੋਂ ਟਿੱਕ ਨਹੀਂ ਹੈ। ਕਿਸੇ ਵੀ ਸਮੇਂ STOP ਲਿਖ ਕੇ ਜਵਾਬ ਦਿਓ। ਤੁਹਾਡੇ {unit} ਹਰ ਹਾਲ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਹਨ।",
