  "sh.priv.m.delBody": "ਤੁਹਾਡਾ ਕਾਰਡ ਹਰ ਦੁਕਾਨ ਤੇ ਚੱਲਣਾ ਬੰਦ ਹੋ ਜਾਂਦਾ ਹੈ। {shops} ਤੇ ਤੁਸੀਂ ਜੋ ਕੁਝ ਜੋੜਿਆ ਹੈ (ਪੁਆਇੰਟ, ਸਟੈਂਪ ਅਤੇ ਇਨਾਮ) ਉਹ ਚਲਾ ਜਾਵੇਗਾ। ਕਾਨੂੰਨ ਅਨੁਸਾਰ ਦੁਕਾਨਾਂ ਪਿਛਲੀ ਖ਼ਰੀਦਦਾਰੀ ਦਾ ਰਿਕਾਰਡ ਤੁਹਾਡੇ ਨਾਮ ਤੋਂ ਬਿਨਾਂ ਰੱਖਦੀਆਂ ਹਨ।",
  "sh.priv.m.openWork": "ਪਹਿਲਾਂ {shop} ਤੇ ਆਪਣੀ ਖੁੱਲ੍ਹੀ ਮੁਰੰਮਤ ਜਾਂ ਆਰਡਰ ਪੂਰਾ ਕਰੋ ਜਾਂ ਰੱਦ ਕਰੋ।",
