  "sh.priv.m.howShops": "ਦੁਕਾਨਾਂ ਤੁਹਾਡਾ ਡੇਟਾ ਕਿਵੇਂ ਵਰਤਦੀਆਂ ਹਨ",
  "sh.priv.m.cantUndo": "ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ। ਤੁਹਾਡਾ ਕਾਰਡ ਹਰ ਥਾਂ ਚੱਲਣਾ ਬੰਦ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਪੁਆਇੰਟ ਚਲੇ ਜਾਂਦੇ ਹਨ।",
  "sh.shops.intro": "ਤੁਸੀਂ ਤੈਅ ਕਰਦੇ ਹੋ ਕਿ ਕੌਣ ਤੁਹਾਨੂੰ ਆਫ਼ਰ ਭੇਜ ਸਕਦਾ ਹੈ। ਦੋਵਾਂ ਹਾਲਤਾਂ ਵਿੱਚ ਤੁਹਾਡੇ ਪੁਆਇੰਟ ਕੰਮ ਕਰਦੇ ਹਨ।",
