  "cp.ad.whyBody": "{shop} ਨੇ {street} ਦੇ ਨੇੜੇ ਰਹਿਣ ਵਾਲਿਆਂ ਨੂੰ ਇਹ ਆਫ਼ਰ ਵਿਖਾਉਣ ਲਈ ਭੁਗਤਾਨ ਕੀਤਾ ਹੈ। ਸਪਾਂਸਰਡ ਪੋਸਟਾਂ ਤੁਹਾਡੇ {terminology} ਨੂੰ ਕਦੇ ਨਹੀਂ ਬਦਲਦੀਆਂ।",
