  "cp.empty.ordersBody": "ਜਦੋਂ ਤੁਸੀਂ ਪਹਿਲਾਂ ਤੋਂ ਆਰਡਰ ਕਰੋਗੇ ਜਾਂ ਕੁਝ ਜਮ੍ਹਾਂ ਕਰਵਾਓਗੇ, ਤਾਂ ਉਸ ਦੀ ਸਥਿਤੀ ਇੱਥੇ ਵੇਖ ਸਕੋਗੇ।",
  "cp.empty.walletBody": "ਨਕਸ਼ੇ ’ਤੇ ਕਿਸੇ ਵੀ ਦੁਕਾਨ ਵਿੱਚ ਆਪਣਾ ਕਾਰਡ ਵਿਖਾਓ ਅਤੇ ਤੁਹਾਡੇ ਪਹਿਲੇ ਪੁਆਇੰਟ ਇੱਥੇ ਆ ਜਾਣਗੇ।",
