  "mkt.solo.trust": "ਸ਼ੁਰੂ ਕਰਨਾ ਮੁਫ਼ਤ · ਮੁਫ਼ਤ ਪਲਾਨ ਵਿੱਚ ਡਿਪਾਜ਼ਿਟ · ਕੀਮਤਾਂ CAD ਵਿੱਚ",
