  "mkt.solo.sample": "ਨਮੂਨੇ ਦਾ ਪ੍ਰੋਫ਼ੈਸ਼ਨਲ, ਨਮੂਨੇ ਦੀਆਂ ਸੇਵਾਵਾਂ ਅਤੇ ਸਮਾਂ। ਤੁਹਾਡੇ ਕੋਲ ਤੁਹਾਡੀ ਆਪਣੀ ਜਾਣਕਾਰੀ ਦਿਖਾਈ ਦੇਵੇਗੀ।",
  "mkt.solo.nail.eyebrow": "ਨੇਲ, ਬ੍ਰੋ ਅਤੇ ਲੈਸ਼ ਟੈਕਨੀਸ਼ੀਅਨਾਂ ਲਈ",
  "mkt.solo.nail.cta": "ਮੁਫ਼ਤ ਆਪਣਾ ਬੁਕਿੰਗ ਲਿੰਕ ਲਓ",
  "mkt.solo.nail.title": "ਜੇ ਤੁਸੀਂ ਨੇਲ ਟੈਕ ਹੋ, ਤਾਂ DM ਵਿੱਚ ਬੁਕਿੰਗ ਲੈਣੀ ਬੰਦ ਕਰੋ।",
  "mkt.solo.nail.sub": "Instagram ਦੇ ਸੁਨੇਹੇ, ਈਮੇਲਾਂ, ਇੱਕ ਵਾਰ ਭੇਜਿਆ ਕੈਲੰਡਰ ਲਿੰਕ। ਇਨ੍ਹਾਂ ਦੀ ਥਾਂ ਆਪਣੀ ਬੁਕਿੰਗ, ਡਿਪਾਜ਼ਿਟ ਅਤੇ ਨਿਯਮਿਤ ਗਾਹਕ ਇੱਕੋ ਥਾਂ ਰੱਖੋ।",
  "mkt.solo.brows.eyebrow": "ਬ੍ਰੋ ਟੈਕਨੀਸ਼ੀਅਨਾਂ ਲਈ",
  "mkt.solo.brows.title": "ਜੇ ਤੁਸੀਂ ਬ੍ਰੋ ਟੈਕ ਹੋ, ਤਾਂ ਗਾਹਕਾਂ ਨੂੰ ਇੱਕ ਅਜਿਹਾ ਲਿੰਕ ਦਿਓ ਜਿਸ ਨਾਲ ਬੁਕਿੰਗ ਹੋ ਜਾਵੇ।",
  "mkt.solo.brows.sub": "\"ਸ਼ਨਿੱਚਰਵਾਰ ਨੂੰ ਕਿਹੜੇ ਸਮੇਂ ਖ਼ਾਲੀ ਹਨ?\" ਪੁੱਛਣ ਦੀ ਲੋੜ ਨਹੀਂ। ਗਾਹਕ ਸਮਾਂ ਚੁਣਦੇ ਹਨ, ਡਿਪਾਜ਼ਿਟ ਦਿੰਦੇ ਹਨ ਅਤੇ ਯਾਦ-ਦਹਾਨੀ ਪਾਉਂਦੇ ਹਨ। ਤੁਹਾਡਾ Instagram ਉਵੇਂ ਹੀ ਰਹਿੰਦਾ ਹੈ।",
  "mkt.solo.lashes.eyebrow": "ਲੈਸ਼ ਟੈਕਨੀਸ਼ੀਅਨਾਂ ਲਈ",
  "mkt.solo.lashes.title": "ਜੇ ਤੁਸੀਂ ਲੈਸ਼ ਟੈਕ ਹੋ, ਤਾਂ ਫ਼ਿਲ ਦੀ ਬੁਕਿੰਗ DM ਵਿੱਚ ਨਹੀਂ ਰਹਿਣੀ ਚਾਹੀਦੀ।",
  "mkt.solo.lashes.sub": "ਹਰ ਤਿੰਨ ਹਫ਼ਤੇ ਬਾਅਦ ਇੱਕ ਫ਼ਿਲ, ਅਤੇ ਹਰ ਫ਼ਿਲ ਸੁਨੇਹਿਆਂ ਦੀ ਇੱਕ ਲੜੀ। ਗਾਹਕ ਇੱਕੋ ਲਿੰਕ ਤੋਂ ਦੁਬਾਰਾ ਬੁੱਕ ਕਰਦੇ ਹਨ, ਅਤੇ ਸਮਾਂ ਆਉਣ ਤੇ ਅਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਯਾਦ ਕਰਵਾਉਂਦੇ ਹਾਂ।",
  "mkt.solo.makeup.eyebrow": "ਮੇਕਅੱਪ ਆਰਟਿਸਟਾਂ ਲਈ",
  "mkt.solo.makeup.title": "ਜੇ ਮੇਕਅੱਪ ਤੁਹਾਡਾ ਕੰਮ ਹੈ, ਤਾਂ ਤਾਰੀਖ਼ ਤੋਂ ਪਹਿਲਾਂ ਡਿਪਾਜ਼ਿਟ ਲੈ ਲਓ।",
  "mkt.solo.makeup.sub": "ਟ੍ਰਾਇਲ, ਦੁਲਹਨ, ਸਮਾਗਮ। ਗਾਹਕ ਸੇਵਾ ਚੁਣਦੇ ਹਨ, ਡਿਪਾਜ਼ਿਟ ਦਿੰਦੇ ਹਨ ਅਤੇ ਉਹ ਦਿਨ ਉਨ੍ਹਾਂ ਦਾ ਹੋ ਜਾਂਦਾ ਹੈ। ਤੁਹਾਡਾ ਪਤਾ ਨਿੱਜੀ ਰਹਿੰਦਾ ਹੈ।",
  "mkt.solo.barber.eyebrow": "ਬਾਰਬਰਾਂ ਅਤੇ ਥ੍ਰੈਡਿੰਗ ਬਾਰਾਂ ਲਈ",
  "mkt.solo.barber.cta": "ਮੁਫ਼ਤ ਸ਼ੁਰੂ ਕਰੋ",
  "mkt.solo.barber.title": "ਜੇ ਤੁਸੀਂ ਬਾਰਬਰ ਹੋ, ਤਾਂ ਆਪਣਾ ਸਾਰਾ ਕੰਮ ਇੱਕੋ ਥਾਂ ਸੰਭਾਲੋ।",
  "mkt.solo.barber.sub": "ਬੁਕਿੰਗ, ਵਾਕ-ਇਨ ਦੀ ਕਤਾਰ, ਪਰਿਵਾਰ ਦੇ ਕਾਰਡ ਅਤੇ ਕੁਰਸੀ ਕਿਰਾਏ ਤੇ ਲੈਣ ਵਾਲੇ। ਪੂਰੀ ਦੁਕਾਨ ਲਈ ਇੱਕ ਕੀਮਤ, ਕੁਰਸੀਆਂ ਭਾਵੇਂ ਜਿੰਨੀਆਂ ਹੋਣ।",
  "mkt.solo.groom.eyebrow": "ਪਾਲਤੂ ਜਾਨਵਰਾਂ ਦੇ ਗਰੂਮਰਾਂ ਲਈ",
