  "mkt.solo.groom.sub": "ਹਰ ਪਾਲਤੂ ਦੀ ਪ੍ਰੋਫ਼ਾਈਲ ਤੇ ਟੀਕਿਆਂ ਦੀਆਂ ਤਾਰੀਖ਼ਾਂ, ਕੁੱਤੇ ਦੇ ਆਕਾਰ ਮੁਤਾਬਕ ਕੀਮਤਾਂ, ਅਤੇ ਮੈਕਸ ਦੀ ਵਾਰੀ ਆਉਣ ਤੇ ਦੁਬਾਰਾ ਬੁੱਕ ਕਰਨ ਦੀ ਯਾਦ।",
