  "mkt.solo.regulars.sub": "ਨਿਯਮਿਤ ਗਾਹਕ ਹੀ ਪੂਰਾ ਕਾਰੋਬਾਰ ਹਨ। ਉਨ੍ਹਾਂ ਨੂੰ ਆਪਣੇ ਫ਼ੋਨ ਤੇ ਤੁਹਾਡਾ ਸਟੈਂਪ ਕਾਰਡ, ਤੁਹਾਡੇ ਪ੍ਰੋਮੋ ਅਤੇ ਇੱਕ ਅਜਿਹਾ ਪਾਸ ਮਿਲਦਾ ਹੈ ਜੋ ਤੁਹਾਡੀ ਗਲੀ ਦੀਆਂ ਹੋਰ ਦੁਕਾਨਾਂ ਤੇ ਵੀ ਚੱਲਦਾ ਹੈ।",
