  "webpush.prompt.title": "ਇਸ ਫ਼ੋਨ ਤੇ ਆਪਣੀ ਯਾਦ-ਦਹਾਨੀ ਪਾਓ",
  "webpush.prompt.body": "ਨੋਟੀਫ਼ਿਕੇਸ਼ਨ ਚਾਲੂ ਕਰੋ, ਅਸੀਂ ਇੱਕ ਦਿਨ ਪਹਿਲਾਂ ਯਾਦ ਕਰਵਾ ਦੇਵਾਂਗੇ। ਟੈਕਸਟ ਦੀ ਲੋੜ ਨਹੀਂ।",
