  "webpush.prompt.on": "ਇਸ ਫ਼ੋਨ ਤੇ ਯਾਦ-ਦਹਾਨੀਆਂ ਚਾਲੂ ਹਨ।",
  "webpush.prompt.denied": "ਇਸ ਸਾਈਟ ਲਈ ਨੋਟੀਫ਼ਿਕੇਸ਼ਨ ਬੰਦ ਹਨ। ਇੱਥੇ ਯਾਦ-ਦਹਾਨੀਆਂ ਪਾਉਣ ਲਈ ਉਨ੍ਹਾਂ ਨੂੰ ਬ੍ਰਾਊਜ਼ਰ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਚਾਲੂ ਕਰੋ।",
  "webpush.prompt.iosTitle": "ਇਸ ਪੰਨੇ ਨੂੰ ਹੋਮ ਸਕ੍ਰੀਨ ਤੇ ਜੋੜੋ",
  "webpush.prompt.ios": "iPhone ਤੇ ਸ਼ੇਅਰ ਦਬਾਓ, ਫਿਰ \"ਹੋਮ ਸਕ੍ਰੀਨ ਤੇ ਜੋੜੋ\" ਚੁਣੋ। ਯਾਦ-ਦਹਾਨੀਆਂ ਚਾਲੂ ਕਰਨ ਲਈ ਇਸਨੂੰ ਹੋਮ ਸਕ੍ਰੀਨ ਤੋਂ ਖੋਲ੍ਹੋ।",
  "webpush.prompt.unsupported": "ਇਹ ਬ੍ਰਾਊਜ਼ਰ ਯਾਦ-ਦਹਾਨੀਆਂ ਨਹੀਂ ਦਿਖਾ ਸਕਦਾ। ਅਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਈਮੇਲ ਰਾਹੀਂ ਭੇਜ ਦੇਵਾਂਗੇ।",
