  "trial.card.startTitle": "ਤੁਹਾਡਾ ਲਿੰਕ ਲਾਈਵ ਹੈ। {plan} {days} ਦਿਨਾਂ ਲਈ ਮੁਫ਼ਤ ਚਾਲੂ ਹੈ।",
  "trial.card.startBody": "ਨਾ ਕਾਰਡ, ਨਾ ਕੁਝ ਰੱਦ ਕਰਨਾ। ਅਗਲੇ ਦੋ ਹਫ਼ਤੇ, ਰੱਦ ਹੋਏ ਸਲਾਟ ਵੇਟਲਿਸਟ ਨੂੰ ਜਾਂਦੇ ਹਨ, ਜਿਨ੍ਹਾਂ ਕਲਾਇੰਟਾਂ ਦਾ ਸਮਾਂ ਹੋ ਗਿਆ ਹੈ ਉਨ੍ਹਾਂ ਨੂੰ ਦੁਬਾਰਾ ਬੁੱਕ ਕਰਨ ਦੇ ਲਿੰਕ ਨਾਲ ਰਿਮਾਈਂਡਰ ਮਿਲਦਾ ਹੈ, ਹਰ ਵਿਜ਼ਿਟ ਤੋਂ ਬਾਅਦ ਰਿਵਿਊ ਦੀ ਬੇਨਤੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਐਤਵਾਰ ਨੂੰ ਤੁਹਾਡਾ ਹਫ਼ਤਾ ਅੰਕੜਿਆਂ ਨਾਲ ਆਉਂਦਾ ਹੈ। {date} ਨੂੰ ਇਹ ਵਾਪਸ Free ਉੱਤੇ ਚਲਾ ਜਾਵੇਗਾ, ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਨਾ ਰੱਖੋ। ਤੁਹਾਡੀਆਂ ਬੁਕਿੰਗਾਂ ਅਤੇ ਕਲਾਇੰਟ ਦੋਵੇਂ ਹਾਲਤਾਂ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ।",
  "trial.card.seeOn": "ਵੇਖੋ ਕੀ ਚਾਲੂ ਹੈ",
  "trial.card.goal": "ਹਫ਼ਤੇ ਦਾ ਟੀਚਾ ਰੱਖੋ",
  "trial.card.endsTitle": "{plan} {weekday} ਨੂੰ ਖ਼ਤਮ ਹੋਵੇਗਾ।",
  "trial.card.soFar": "ਹੁਣ ਤੱਕ: {fills} ਰੱਦ ਸਲਾਟ ਭਰੇ, {rebooked} ਕਲਾਇੰਟ ਰਿਮਾਈਂਡਰ ਨਾਲ ਦੁਬਾਰਾ ਬੁੱਕ ਹੋਏ, {reviews} ਰਿਵਿਊ ਬੇਨਤੀਆਂ ਗਈਆਂ, {addons} ਐਡ-ਆਨ ਬੁੱਕ ਹੋਏ। ਯਾਨੀ ਲਗਭਗ {amount} ਜਿਨ੍ਹਾਂ ਪਿੱਛੇ ਤੁਹਾਨੂੰ ਭੱਜਣਾ ਨਹੀਂ ਪਿਆ।",
  "trial.card.price": "{plan} {price} ਮਹੀਨਾ ਹੈ, ਜਾਂ ਤੁਹਾਡੀ ਵੈੱਬਸਾਈਟ ਨਾਲ {annual} ਸਾਲ।",
  "trial.card.quiet": "ਹੁਣ ਤੱਕ ਸ਼ਾਂਤੀ ਰਹੀ ਹੈ, ਪਹਿਲੇ ਦੋ ਹਫ਼ਤਿਆਂ ਵਿੱਚ ਇਹ ਆਮ ਹੈ। {plan} ਜਦੋਂ ਚਾਹੋ {price} ਮਹੀਨਾ ਹੈ; ਤੁਹਾਡੀ ਵੇਟਲਿਸਟ ਅਤੇ ਰਿਮਾਈਂਡਰ ਉਸੇ ਦਿਨ ਚਾਲੂ ਹੋ ਜਾਂਦੇ ਹਨ।",
