  "trial.card.letEnd": "ਖ਼ਤਮ ਹੋਣ ਦਿਓ",
  "trial.receipt.title": "{plan} ਅੱਜ ਖ਼ਤਮ ਹੋਇਆ। ਇਸਨੇ ਇਹ ਕੀਤਾ।",
  "trial.receipt.summary": "{days} ਦਿਨ · {bookings} ਬੁਕਿੰਗਾਂ · {amount} ਬੁੱਕ ਹੋਇਆ",
  "trial.receipt.parts": "{fills} ਰੱਦ ਸਲਾਟ ਭਰੇ · {rebooked} ਰਿਮਾਈਂਡਰ ਨਾਲ ਦੁਬਾਰਾ ਬੁੱਕ · {reviews} ਰਿਵਿਊ ਬੇਨਤੀਆਂ · {addons} ਐਡ-ਆਨ",
  "trial.receipt.paused": "ਤੁਹਾਡੀ ਵੇਟਲਿਸਟ, ਰਿਮਾਈਂਡਰ ਅਤੇ ਰਿਵਿਊ ਬੇਨਤੀਆਂ ਰੁਕੀਆਂ ਹਨ, ਮਿਟਾਈਆਂ ਨਹੀਂ ਗਈਆਂ। ਐਡ-ਆਨ ਤੁਹਾਡੀਆਂ ਸੇਵਾਵਾਂ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਜਿਸ ਦਿਨ ਤੁਸੀਂ {plan} ਚਾਲੂ ਕਰੋ, ਬੁਕਿੰਗ ਪੇਜ ਉੱਤੇ ਵਾਪਸ ਆ ਜਾਂਦੇ ਹਨ।",
