  "trial.banner.liveBody": "ਵੇਟਲਿਸਟ, ਆਪਣੇ-ਆਪ ਰਿਮਾਈਂਡਰ, ਰਿਵਿਊ ਬੇਨਤੀਆਂ, ਐਡ-ਆਨ ਅਤੇ ਐਤਵਾਰ ਦੀ ਰਿਪੋਰਟ ਚਾਲੂ ਹਨ। ਕੋਈ ਕਾਰਡ ਨਹੀਂ: ਖ਼ਤਮ ਹੋਣ ਉੱਤੇ ਤੁਸੀਂ Free ਉੱਤੇ ਵਾਪਸ ਜਾਂਦੇ ਹੋ ਅਤੇ ਸਭ ਕੁਝ ਰਹਿੰਦਾ ਹੈ।",
